import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { VolunteerInspectionPage } from './volunteer-inspection.page';

const routes: Routes = [
  {
    path: '',
    component: VolunteerInspectionPage
  },
  {
    path: 'my-inspections',
    loadChildren: () => import('./my-inspections/my-inspections.module').then( m => m.MyInspectionsPageModule)
  },
  {
    path: 'student-attendance',
    loadChildren: () => import('./student-attendance/student-attendance.module').then( m => m.StudentAttendancePageModule)
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class VolunteerInspectionPageRoutingModule {}
